import { GlideRecord, gs } from '@servicenow/glide'
import type { MySampleType } from './types-example'
import { MyAppTables } from './constants'

export function rule(current: GlideRecord, previous: GlideRecord) {
    gs.info(current.getUniqueValue() + previous.getUniqueValue())

    const foo: MySampleType = {
        a: true,
        b: 'hello',
    }

    gs.info(`foo: ${foo.a} ${foo.b}`)
    const record = new GlideRecord(MyAppTables.x_foo_1.toString())
    record.query()
}
